# Compare Hamilton and Russell on lap 38
drivers = {d['abbreviation']: d['driver_number'] for d in load('drivers_11388.json')}
rows = {c: load(f"laps_11388_{drivers[c]}.json") for c in ('HAM', 'RUS')}
def lap(code, n):
    return next(r for r in rows[code] if r['lap_number'] == n)
def elapsed(code, n):
    return sum(r['lap_time_ms'] for r in rows[code] if r['lap_number'] <= n and r['lap_time_ms']) / 1000
for code in ('HAM', 'RUS'):
    r = lap(code, 38)
    print(code, f"P{r['position']}", r['compound'], f"tyre age {r['tyre_life_laps']} laps", f"lap time {r['lap_time_ms'] / 1000:.3f} s")
print(f"Lap 38: Hamilton faster by {(lap('RUS', 38)['lap_time_ms'] - lap('HAM', 38)['lap_time_ms']) / 1000:.3f} s")
print(f"Race time after lap 38: Russell {elapsed('RUS', 38) - elapsed('HAM', 38):.1f} s behind Hamilton")
series = []
for code, color in (('HAM', '#3d7f8a'), ('RUS', '#d9822b')):
    # laps over 105 s are neutralised laps that would flatten the racing laps
    data = [[r['lap_number'], r['lap_time_ms'] / 1000] for r in rows[code]
            if 30 <= r['lap_number'] <= 46 and r['lap_time_ms'] and r['lap_time_ms'] < 105000]
    series.append({'name': code, 'type': 'line', 'showSymbol': False, 'lineStyle': {'color': color, 'width': 2}, 'data': data})
option = {'tooltip': {'trigger': 'axis'}, 'legend': {'top': 0}, 'xAxis': {'type': 'value', 'name': 'Lap', 'min': 30, 'max': 46},
          'yAxis': {'type': 'value', 'name': 'Lap time (s)', 'scale': True}, 'series': series}
emit_chart(option, 'Laps 30 to 46: Hamilton vs Russell')

